一个三页面项目，配置里确保有：

```js
// vite.config.ts 参考
export default defineConfig({
  build: {
    rollupOptions: {
      output: {
        entryFileNames: '[name].[contenthash:8].js',
        chunkFileNames: '[name].[contenthash:8].js',
        assetFileNames: '[name].[contenthash:8][extname]',
      },
    },
  },
});
```
